  static int cxl_reset_execute(struct pci_dev *pdev, int dvsec)
  {
        u16 cap;
        int rc;

        rc = pci_read_config_word(pdev, dvsec + PCI_DVSEC_CXL_CAP, &cap);
        if (rc)
