static void cxl_hdm_info_free(struct cxl_hdm_info *info)
{
	kfree(info->decoder_state);
	kfree(info);
}
DEFINE_FREE(cxl_hdm_info, struct cxl_hdm_info *, if (_T) cxl_hdm_info_free(_T))
